<template>
  <div>
    <h2>个人中心</h2>
    <el-card style="max-width: 600px;">
      <el-form label-width="100px">
        <el-form-item label="用户名">
          <span>{{ userInfo.username }}</span>
        </el-form-item>
        <el-form-item label="姓名">
          <span>{{ userInfo.realName }}</span>
        </el-form-item>
        <el-form-item label="角色">
          <span>{{ roleText }}</span>
        </el-form-item>
        <el-form-item label="邮箱">
          <span>{{ userInfo.email }}</span>
        </el-form-item>
        <el-form-item label="电话">
          <span>{{ userInfo.phone }}</span>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="showPasswordDialog = true">修改密码</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 修改密码对话框 -->
    <!-- eslint-disable-next-line vue/no-deprecated-v-bind-sync --> 
    <el-dialog title="修改密码" :visible.sync="showPasswordDialog" width="400px">
      <el-form :model="pwdForm" :rules="pwdRules" ref="pwdForm">
        <el-form-item label="原密码" prop="oldPassword">
          <el-input v-model="pwdForm.oldPassword" type="password" />
        </el-form-item>
        <el-form-item label="新密码" prop="newPassword">
          <el-input v-model="pwdForm.newPassword" type="password" />
        </el-form-item>
        <el-form-item label="确认密码" prop="confirmPassword">
          <el-input v-model="pwdForm.confirmPassword" type="password" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="showPasswordDialog = false">取消</el-button>
        <el-button type="primary" @click="changePassword">确认</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { mapState } from 'vuex'

export default {
  name: 'UserProfile',
  data() {
    return {
      showPasswordDialog: false,
      pwdForm: {
        oldPassword: '',
        newPassword: '',
        confirmPassword: ''
      },
      pwdRules: {
        oldPassword: [{ required: true, message: '请输入原密码', trigger: 'blur' }],
        newPassword: [
          { required: true, message: '请输入新密码', trigger: 'blur' },
          { min: 6, message: '密码长度至少6位', trigger: 'blur' }
        ],
        confirmPassword: [
          { required: true, message: '请确认新密码', trigger: 'blur' },
          { validator: (rule, value, callback) => {
            if (value !== this.pwdForm.newPassword) {
              callback(new Error('两次输入密码不一致'))
            } else {
              callback()
            }
          }, trigger: 'blur' }
        ]
      }
    }
  },
  computed: {
    ...mapState('user', ['userInfo']),
    roleText() {
      const map = { admin: '管理员', user: '普通用户' }
      return map[this.userInfo?.role] || this.userInfo?.role
    }
  },
  created() {
    if (!this.userInfo) {
      this.$store.dispatch('user/fetchUserInfo')
    }
  },
  methods: {
    changePassword() {
      this.$refs.pwdForm.validate(async valid => {
        if (valid) {
          // 调用修改密码 API
          await this.$store.dispatch('user/changePassword', this.pwdForm)
          this.$message.success('密码修改成功')
          this.showPasswordDialog = false
          this.pwdForm = { oldPassword: '', newPassword: '', confirmPassword: '' }
        }
      })
    }
  }
}
</script>